/** Two-process scheduling fixture. Synthetic adapter only, NEVER a model. */
import fs from 'node:fs';import {createBridgeServer} from '../../lib/server.js';import {serveStdio} from '../../lib/stdio-lifecycle.js';
const bridge=createBridgeServer({env:process.env,runTaskImpl:async input=>{const sid=input.sessionId??'synthetic-native-'+input.taskId;fs.mkdirSync(input.sessionRoot,{recursive:true});input.onSession(sid,input.workspace,{verified:true});input.onReport({eventId:'entered-'+input.taskId,text:'synthetic backend entered',data:{pid:process.pid,sessionId:sid}});if(input.prompt==='hold')await new Promise(resolve=>{if(input.signal.aborted)resolve();else input.signal.addEventListener('abort',resolve,{once:true});});return {taskId:input.taskId,conversationKey:input.conversationKey,state:input.signal.aborted?'cancelled':'completed',answer:'synthetic only',reason:{kind:input.signal.aborted?'cancelled':'completed'},sessionId:sid,cwd:input.workspace,treeExited:true,exitCode:0};}});await serveStdio(bridge.server);
